args.query:
INSERT INTO changelog (entry_id, author, date, message)
VALUES (
  (SELECT 'chg-' || strftime('%Y%m%d%H%M%f','now')),
  'openhands-agent',
  CURRENT_TIMESTAMP,
  (SELECT 'Created shared_export archive record with included_ids=' || 
           COALESCE((SELECT '[' || group_concat(experiment_id, ',') || ']' FROM experiments e WHERE date(e.created_at) < date('now','-2 years') AND lower(e.metadata) NOT LIKE '%export_block%'), '[]') ||
           ' and excluded_ids=' || 
           COALESCE((SELECT '[' || group_concat(experiment_id, ',') || ']' FROM experiments e WHERE date(e.created_at) < date('now','-2 years') AND lower(e.metadata) LIKE '%export_block%'), '[]') ||
           '. See shared_export for payload and export_id.'
   )
);
SELECT last_insert_rowid() as changelog_rowid;
